// Ambil semua berita dari node sebelumnya
const items = $input.all();
const grouped = {};

items.forEach(item => {
    const news = item.json;

    // Ambil identifier (Gunakan fallback jika data kosong)
    const source = news.source || "umum";
    const category = news.category || "terbaru";

    // Inisialisasi struktur jika belum ada
    if (!grouped[source]) {
        grouped[source] = {};
    }
    if (!grouped[source][category]) {
        grouped[source][category] = [];
    }

    // SANITASI: Hapus thumbnail dan hanya ambil data teks penting
    const { thumbnail, ...cleanData } = news;

    grouped[source][category].push(cleanData);
});

// SORTING: Urutkan setiap list berita per kategori berdasarkan waktu terbaru
for (const s in grouped) {
  for (const c in grouped[s]) {
    grouped[s][c].sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));
  }
}

// Kembalikan sebagai SATU buah object JSON besar untuk dianalisis AI sekaligus
return { 
  json: {
    total_berita: items.length,
    waktu_analisis: new Date().toLocaleString('id-ID'),
    data: grouped 
  }
};

