function formatTelegramHTML(text) {

  // Bold judul utama
  text = text.replace(/^💥(.+)/m, '<b>💥$1</b>');

  // Bold judul berita (1. Judul)
  text = text.replace(/^(\d+\.\s.+)$/gm, '<b>$1</b>');

  // Convert semua URL menjadi HTML link
  text = text.replace(
    /(https?:\/\/[^\s]+)/g,
    '<a href="$1">$1</a>'
  );

  return text;
}

const html = formatTelegramHTML($json.text);

return [
  {
    html: html
  }
];

function formatFacebook(text) {

  let lines = text.split("\n");
  let result = [];

  for (let line of lines) {

    // hapus emoji link
    line = line.replace("🔗 ", "");

    // beri jarak sebelum nomor berita
    if (/^\d+\.\s/.test(line)) {
      result.push("");
      result.push(line);
      continue;
    }

    // jika URL
    if (/https?:\/\/\S+/.test(line)) {
      result.push(line);
      result.push("");
      continue;
    }

    result.push(line);
  }

  return result.join("\n").trim();
}

const fbText = formatFacebook($json.text);

return [
  {
    facebook: fbText
  }
];

